                # Ray from marker to its vertical rail.
                step = 1 if own_pos > c else -1
                cc = c + step
                while 0 <= cc < w and grid[r][cc] != rail_color:
                    out[r][cc] = mark_color
                    cc += step

                mapped_r = other_span[0] + (u - own_span[0])
                if 0 <= mapped_r < h:
                    for cc in range(min(pa, pb), max(pa, pb) + 1):
                        if grid[mapped_r][cc] != rail_color:
                            out[mapped_r][cc] = mark_color

    return out
